#include <iostream>

class Rectangle {
    const int m_width;
    const int m_height;
public:
    Rectangle(int width, int height)
        : m_width{ width }, m_height{ height }
    {}

    int area() const { return m_width * m_height; }
};

int main() {
    int w{}, h{};
    std::cin >> w >> h;
    Rectangle r{ w, h };
    std::cout << "Area: " << r.area() << "\n";
}

