#include <iostream>

class Incrementer {
    int& m_target;        // reference member: must be bound in the initializer list
    const int m_amount;   // const member: must be set in the initializer list
public:
    // TODO: Write a constructor Incrementer(int& target, int amount).
    // A reference member and a const member can only be set with a member
    // initializer list (lesson 14.10) -- they cannot be assigned in the body.
    // Bind m_target to target, and set m_amount from amount.

    // apply() adds m_amount to whatever m_target refers to.
    void apply() const { m_target += m_amount; }
};

int main() {
    int initial{}, amount{}, count{};
    std::cin >> initial >> amount >> count;

    int total{ initial };
    Incrementer inc{ total, amount };
    for (int i{ 0 }; i < count; ++i)
        inc.apply();

    std::cout << "Total: " << total << "\n";
}

solution_code:
#include <iostream>

class Incrementer {
    int& m_target;
    const int m_amount;
public:
    Incrementer(int& target, int amount)
        : m_target{ target }, m_amount{ amount }
    {}

    void apply() const { m_target += m_amount; }
};

int main() {
    int initial{}, amount{}, count{};
    std::cin >> initial >> amount >> count;

    int total{ initial };
    Incrementer inc{ total, amount };
    for (int i{ 0 }; i < count; ++i)
        inc.apply();

    std::cout << "Total: " << total << "\n";
}
